#
# classify-manifest-outcome.sh <код-возврата-make> <файл-с-выводом>
#
# Выносит вердикт ШАГА «манифесты модулей» по ТЕКСТУ вывода исполнителя формы
# (`make module-manifest-check`) и выходит кодом самого шага. Развилка живёт
# здесь, а не в теле `run:`: развилку внутри шага нечем доказать инъекцией, а у
# этого файла есть самопроверка (`--self-test`), и конвейер зовёт её ДО вердикта.
#
# Исходы разбора и что с ними делает шаг:
#
#   ЗЕЛЁНОЕ             код make 0: каждый найденный манифест прочитан, разобран
#                       и связен                                     → шаг 0;
#   КРАСНОЕ             строка `НАХОДКА:` — манифест негоден, названы файл, поле
#                       и строка                                     → шаг 1;
#   НЕ ИСПОЛНЯЛАСЬ      проверка не исполнилась (вызов не разобран, дерево под
#                       гейтом не то, канон или каталог прав не прочитаны) —
#                       вердикта о форме нет                         → шаг 1;
#   УСЛОВИЕ НЕ СОЗДАНО  манифестов не найдено ни одного — «проверять нечего»;
#                       это не дефект формы и не успех: аннотация `::error`
#                       называет исход, шаг не роняется               → шаг 0;
#   НЕ РАЗОБРАНО        ненулевой код без строки-маркера либо вывод не прочитан —
#                       о форме не сказано НИЧЕГО                    → шаг 2.
#
# Почему «проверять нечего» называется, но шаг не роняет: схлопни его в успех
# молча — пустое дерево отчитывалось бы зелёным так же уверенно, как
# проверенное, и первый манифест, положенный мимо ожидаемого имени, остался бы
# невидимым навсегда; схлопни в отказ — красным стал бы ствол, а не продукт.
#
# ─────────────────────────────────────────────────────────────────────────────
# ПОЧЕМУ ПО ТЕКСТУ, А НЕ ПО КОДУ (kaname#825)
#
# `make` СХЛОПЫВАЕТ код рецепта в свой: исполнитель, вышедший 1 (находка),
# 2 (проверять нечего) и 3 (не исполнялась), одинаково доезжает до оболочки
# ДВОЙКОЙ. Прежнее тело шага разбирало именно код, и двойка означала у него
# «условие не создано, exit 0»: НАСТОЯЩИЙ дефект формы манифеста доезжал до
# ствола зелёным, с заголовком о несозданном условии. Класс тот же, что у соседа
# classify-canon-outcome.sh, — там он закрыт раньше и тем же способом.
#
# ─────────────────────────────────────────────────────────────────────────────
# ПОРЯДОК РАЗБОРА НЕСУЩИЙ
#
# Находка спрашивается ПЕРВОЙ: исполнитель печатает и находки, и затем своё
# «не исполнялась» (проверка прав после находок формы), и обратный порядок
# объявил бы красное «невыполнившимся». Вердикт шага при этом тот же, но
# заголовок посылал бы читателя чинить окружение, а не манифест.
# «Не исполнялась» спрашивается раньше «проверять нечего»: пустой обход
# исполнитель называет «проверять нечего», а проверка прав на пустом обходе
# печатает ту же фразу при своём коде 0 — слово о пустоте не перекрывает отказ.
#
# Маркер находки привязан к НАЧАЛУ СТРОКИ (`^НАХОДКА:`): так его печатает сам
# исполнитель (internal/manifestcheckrun), и то же слово внутри прозы вердиктом
# не становится.
set -uo pipefail

readonly FINDING_RE='^НАХОДКА:'
readonly NOTRUN_RE='НЕ ИСПОЛНЯЛАСЬ'
readonly VOID_RE='проверять нечего'

# Коды исхода разбора — внутренние; наружу шаг выходит кодом из step_code.
readonly O_GREEN=0 O_RED=1 O_UNPARSED=2 O_NOTRUN=3 O_VOID=75

classify() {
    local rc="$1" log="$2"
    if [ ! -r "$log" ]; then
        echo "форма манифестов: НЕ РАЗОБРАНО — вывод исполнителя не прочитан ($log)" >&2
        return "$O_UNPARSED"
    fi
    if [ "$rc" -eq 0 ]; then
        echo "форма манифестов: ЗЕЛЁНОЕ — манифесты прочитаны и годны (код make 0)"
        return "$O_GREEN"
    fi
    if grep -qE "$FINDING_RE" "$log"; then
        echo "форма манифестов: КРАСНОЕ — манифест негоден; файл, поле и строка — в выводе выше" >&2
        return "$O_RED"
    fi
    if grep -qE "$NOTRUN_RE" "$log"; then
        echo "форма манифестов: НЕ ИСПОЛНЯЛАСЬ — вердикта о форме нет; причина — в выводе выше" >&2
        return "$O_NOTRUN"
    fi
    if grep -qE "$VOID_RE" "$log"; then
        echo "форма манифестов: УСЛОВИЕ НЕ СОЗДАНО — манифестов не найдено ни одного, проверять нечего." >&2
        echo "Это не «форма в порядке»: вердикта о форме нет ни зелёного, ни красного." >&2
        return "$O_VOID"
    fi
    echo "форма манифестов: НЕ РАЗОБРАНО — исполнитель вышел кодом $rc и не назвал себя" >&2
    echo "ни одной строкой-маркером. О форме манифестов не сказано НИЧЕГО." >&2
    return "$O_UNPARSED"
}

# step_code <исход> — код шага конвейера и его аннотация. Политика шага — здесь,
# одним местом с разбором, чтобы её доказывала та же самопроверка.
step_code() {
    case "$1" in
        "$O_GREEN") return 0 ;;
        "$O_RED")
            echo "::error title=Форма манифеста негодна::названы файл, поле и строка (вывод выше)"
            return 1 ;;
        "$O_NOTRUN")
            echo "::error title=НЕ ИСПОЛНЯЛАСЬ::проверка формы манифестов не исполнилась — вердикта о форме нет (причина в выводе выше)"
            return 1 ;;
        "$O_VOID")
            echo "::error title=УСЛОВИЕ НЕ СОЗДАНО::манифестов не найдено ни одного — ПРОВЕРЯТЬ НЕЧЕГО. Это третий исход, а не «форма в порядке»"
            return 0 ;;
        *)
            echo "::error title=НЕ РАЗОБРАНО::исполнитель не назвал своего исхода ни одной строкой-маркером — о форме манифестов не сказано НИЧЕГО"
            return 2 ;;
    esac
}

verdict() { # verdict <код-make> <файл-с-выводом> — код шага
    local o=0
    classify "$1" "$2" || o=$?
    step_code "$o"
}

# --- самопроверка: доказательство инъекцией в обе стороны ---------------------
#
# Живёт ФЛАГОМ этого же файла, а не соседним: отдельный файл в перечень шагов
# конвейера не попал бы сам, то есть не исполнялся бы никогда.
if [ "${1:-}" = "--self-test" ]; then
    TMP="$(mktemp -d)"; trap 'rm -rf "$TMP"' EXIT
    probes=0; failed=0
    # run <ждём-исход> <ждём-код-шага> <имя> <код-make> <тело-вывода>
    run() {
        local want="$1" wstep="$2" name="$3" rc="$4" body="$5" got=0 gstep=0
        probes=$((probes + 1))
        printf '%s\n' "$body" > "$TMP/log"
        classify "$rc" "$TMP/log" >/dev/null 2>&1 || got=$?
        verdict "$rc" "$TMP/log" >/dev/null 2>&1 || gstep=$?
        if [ "$got" -ne "$want" ] || [ "$gstep" -ne "$wstep" ]; then
            echo "  ПРОВАЛ $name — ждали исход $want и шаг $wstep, получили $got и $gstep" >&2
            failed=$((failed + 1)); return
        fi
        echo "  ok   $name (исход $got, шаг $gstep)"
    }

    # Тела взяты у самого исполнителя ДОСЛОВНО — прогоном `make
    # module-manifest-check` на дереве модуля и его инъекциях (kaname#825):
    # чистое дерево; лишний ключ верхнего уровня манифеста; манифест снят с
    # индекса; корень с пустым индексом (временный путь заменён на /work/void-tree).
    # «Проверять нечего» — строки исполнителя (internal/manifestcheckrun: Run и
    # checkRights) при обходе без манифестов; строка make — в форме верхнего
    # уровня, как в конвейере. Синтетика доказывала бы, что разбор понимает
    # синтетику.
    census='перепись: осмотрено файлов 4556 · каталогов пропущено 1 · манифестов прочитано 1'
    rights='каталог прав: записей 358 · привязано действий 355 · вне формы модуля 3'
    green="корень обхода: /work/src
$census · находок 0 · таблица типов: образ (объявления таблицы охраняются от присвоения)
  прочитан: manifest.yaml
$rights"
    finding="корень обхода: /work/src
$census · находок 1 · таблица типов: образ (объявления таблицы охраняются от присвоения)
  прочитан: manifest.yaml
НАХОДКА: manifest.yaml: manifest: document does not match the declared shape: yaml: unmarshal errors:
  line 1055: field bogusManifestKey not found in type manifest.Manifest
$rights
make: *** [Makefile:379: module-manifest-check] Error 1"
    notrun='проверка НЕ ИСПОЛНЯЛАСЬ: дерево под гейтом — не то, о котором гейт может говорить
  модуль:  /work/src
  дерево:  /work/src
  ожидался признак: manifest.yaml в составе коммита этого дерева
make: *** [Makefile:379: module-manifest-check] Error 3'
    void='права ролей: манифестов не прочитано ни одного — проверять нечего
манифестов в дереве нет ни одного — это НЕ успех, а «проверять нечего»: манифесты отслеживаются деревом, поэтому пустой обход означает, что до них не дошли — смотрите корень обхода (/work/src), а не форму манифеста
make: *** [Makefile:379: module-manifest-check] Error 2'
    emptyindex='корень обхода: /work/void-tree
перепись: осмотрено файлов 0 · каталогов пропущено 0 · манифестов прочитано 0 · находок 1 · таблица типов: образ (объявления таблицы охраняются от присвоения)
НАХОДКА: /work/void-tree: корень — сам репозиторий, но в его индексе нет ни одного файла — непрочитанное есть НАХОДКА, а не «проверять нечего»: полоса дерева читает состав КОММИТА, а коммит об этом корне не знает ничего
права ролей: манифестов не прочитано ни одного — проверять нечего
make: *** [Makefile:379: module-manifest-check] Error 1'

    echo "=== разбор исхода формы манифестов: доказательство инъекцией ==="
    # (−) ЗАКОННЫЙ БЛИЗНЕЦ: без него всё нижеследующее зеленело бы на разборе,
    #     который краснеет всегда.
    run "$O_GREEN" 0 "(−) код make 0 — годно" 0 "$green"
    # (+) ГЛАВНЫЙ КЛАСС: находка доезжает КРАСНОЙ, хотя make схлопнул её в двойку.
    run "$O_RED" 1 "(+) находка при коде make 2 — КРАСНОЕ, а не «условие не создано»" 2 "$finding"
    # (+) «не исполнялась» при той же двойке — шаг роняется, как и прежде на коде 3.
    run "$O_NOTRUN" 1 "(+) не исполнялась при коде make 2 — шаг роняется" 2 "$notrun"
    # (−) третья категория остаётся третьей: названа, шаг не роняется.
    run "$O_VOID" 0 "(−) проверять нечего при коде make 2 — названо, шаг не роняется" 2 "$void"
    # (+) ПОРЯДОК: пустой индекс — находка, а проверка прав рядом печатает
    #     «проверять нечего»; фраза о пустоте красного не глотает.
    run "$O_RED" 1 "(+) пустой индекс: находка и «проверять нечего» разом — КРАСНОЕ" 2 "$emptyindex"
    # (+) ПОРЯДОК: находки и затем «не исполнялась» разом — побеждает находка.
    run "$O_RED" 1 "(+) находка и «не исполнялась» разом — побеждает находка" 2 \
        "$finding"$'\n'"$notrun"
    # (+) ПОРЯДОК: «не исполнялась» и фраза о пустоте разом — побеждает отказ.
    run "$O_NOTRUN" 1 "(+) «не исполнялась» и «проверять нечего» разом — побеждает отказ" 2 \
        "$void"$'\n'"$notrun"
    # (+) маркер внутри прозы вердиктом не становится.
    run "$O_UNPARSED" 2 "(+) слово «НАХОДКА:» не в начале строки — НЕ РАЗОБРАНО" 2 \
        'сборка упала: см. НАХОДКА: в журнале соседа'
    # (+) исход не назван ни одной строкой — НЕ РАЗОБРАНО, а не «чисто».
    run "$O_UNPARSED" 2 "(+) ненулевой код без маркера — НЕ РАЗОБРАНО" 2 $'сегфолт\nничего не сказано'
    run "$O_UNPARSED" 2 "(+) вывода нет вовсе — НЕ РАЗОБРАНО" 2 ""
    # (+) вывод не прочитан — тоже не «чисто».
    probes=$((probes + 1)); got=0
    verdict 0 "$TMP/нет-такого-файла" >/dev/null 2>&1 || got=$?
    if [ "$got" -ne 2 ]; then
        echo "  ПРОВАЛ (+) вывод недоступен при коде make 0 — ждали шаг 2, получили $got" >&2
        failed=$((failed + 1))
    else
        echo "  ok   (+) вывод недоступен при коде make 0 — НЕ РАЗОБРАНО (шаг 2)"
    fi
    # (+) аннотация несёт исход: «проверять нечего» не молчит при зелёном шаге.
    probes=$((probes + 1))
    printf '%s\n' "$void" > "$TMP/log"
    if verdict 2 "$TMP/log" 2>/dev/null | grep -q '^::error title=УСЛОВИЕ НЕ СОЗДАНО::'; then
        echo "  ok   (+) «проверять нечего» названо аннотацией"
    else
        echo "  ПРОВАЛ (+) «проверять нечего» прошло без аннотации — неотличимо от годного" >&2
        failed=$((failed + 1))
    fi

    echo
    echo "classify-manifest-outcome --self-test: проб исполнено $probes, провалов $failed"
    [ "$probes" -eq 0 ] && { echo "ПРОВАЛ: ни одной пробы не исполнено" >&2; exit 2; }
    [ "$failed" -gt 0 ] && exit 1
    exit 0
fi

if [ "$#" -ne 2 ]; then
    echo "нужно два довода: <код-возврата-make> <файл-с-выводом>" >&2
    exit 2
fi
verdict "$1" "$2"
